<script setup lang="ts">
import { ref } from 'vue'
import { onLoad,onPullDownRefresh } from '@dcloudio/uni-app'
import WareState from '@/shared/components/WareState.vue'
import SessionTrigger from '@/shared/components/SessionTrigger.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
import { distributionTeamApi,type TeamStatistic } from '../../api/distribution-team.api'
const now=new Date().toISOString().slice(0,10);const keyword=ref('');const type=ref<'session'|'month'>('session');const date=ref(now);const month=ref(now.slice(0,7));const picker=ref(false);const list=ref<TeamStatistic[]>([]);const configured=ref(true);const teamName=ref('');const loading=ref(true);const error=ref('');const selected=ref<TeamStatistic>();
async function load(){loading.value=true;error.value='';try{const d=await distributionTeamApi.statistics(keyword.value,type.value,type.value==='session'?date.value:month.value);configured.value=d.configured;teamName.value=d.teamName||'';list.value=d.list}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function chooseMonth(){uni.showModal({title:'选择月份',editable:true,placeholderText:'例如 2026-09',content:month.value,success:r=>{if(r.confirm&&/^\d{4}-\d{2}$/.test(r.content||'')){month.value=r.content!;load()}}})}
onLoad(load);onPullDownRefresh(load)
</script>
<template><view class="page"><view class="team-line"><strong>{{teamName||'配货明细'}}</strong><text>仅统计本人负责团队</text></view><view class="filters"><view class="search"><text>⌕</text><input v-model="keyword" placeholder="姓名或手机号" @confirm="load"/></view><view class="switch"><text :class="{active:type==='session'}" @click="type='session';load()">按场次</text><text :class="{active:type==='month'}" @click="type='month';load()">按月份</text></view><SessionTrigger v-if="type==='session'" :value="date" @click="picker=true"/><view v-else class="month-trigger" @click="chooseMonth">{{month}}⌄</view></view><view class="table-head"><text>员工信息</text><text>配货汇总（扎）</text></view><WareState v-if="loading" type="loading" title="正在统计团队配货"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><WareState v-else-if="!configured" type="empty" title="当前未配置有效的外包配货团队" description="请联系管理员完成配货团队及负责人配置"/><view v-else-if="list.length" class="rows"><view v-for="row in list" :key="row.account_id" class="row" @click="selected=row"><view><strong>{{row.display_name}}</strong><text>{{row.phone}}</text></view><view><strong>{{row.total_num}}</strong><text>扎 ›</text></view></view></view><WareState v-else type="empty" title="暂无配货明细" description="当前统计周期没有团队成员配货记录"/><SessionDatePicker v-model="date" v-model:visible="picker" title="选择场次" @confirm="load"/><view v-if="selected" class="mask" @click.self="selected=undefined"><view class="drawer"><view class="drawer-head"><view><strong>{{selected.display_name}}</strong><text>分区配货明细</text></view><text @click="selected=undefined">关闭</text></view><view class="zone-head"><text>分区</text><text>配货数量（扎）</text></view><scroll-view scroll-y class="zone-list"><view v-for="z in selected.zoneList" :key="z.zone" class="zone-row"><text>{{z.zone_name}}</text><strong>{{z.num}}</strong></view><WareState v-if="!selected.zoneList.length" type="empty" title="暂无分区明细"/></scroll-view></view></view></view></template>
<style scoped lang="scss">.page{min-height:100vh;padding:20rpx 24rpx;background:var(--wms-background)}.team-line,.filters,.search,.switch,.table-head,.row,.row>view,.drawer-head,.drawer-head>view,.zone-head,.zone-row{display:flex;align-items:center}.team-line,.table-head,.row,.drawer-head,.zone-head,.zone-row{justify-content:space-between}.team-line strong{font-size:25rpx}.team-line text{color:var(--wms-text-secondary);font-size:18rpx}.filters{gap:8rpx;margin-top:16rpx}.search{flex:1;min-width:0;height:64rpx;padding:0 12rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff}.search input{min-width:0;width:100%;padding-left:6rpx;font-size:19rpx}.switch{flex-shrink:0;height:64rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;overflow:hidden}.switch text{display:flex;height:100%;padding:0 11rpx;align-items:center;background:#fff;color:var(--wms-text-secondary);font-size:17rpx}.switch .active{background:var(--wms-primary-700);color:#fff}.month-trigger{display:flex;flex-shrink:0;height:62rpx;align-items:center;padding:0 10rpx;border:1rpx solid var(--wms-border);border-radius:8rpx;background:#fff;font-size:18rpx;color:var(--wms-primary-700)}.table-head{height:62rpx;margin-top:18rpx;padding:0 20rpx;background:var(--wms-primary-700);color:#fff;font-size:21rpx}.table-head text:last-child{width:42%;text-align:center}.rows{background:#fff}.row{min-height:88rpx;padding:12rpx 20rpx;border-bottom:1rpx solid var(--wms-border)}.row>view{gap:10rpx}.row>view:first-child{flex-direction:column;align-items:flex-start}.row>view:first-child strong{font-size:22rpx}.row>view:first-child text{color:var(--wms-text-secondary);font-size:18rpx}.row>view:last-child{width:42%;justify-content:center;color:var(--wms-primary-700)}.row>view:last-child strong{font-size:27rpx}.row>view:last-child text{font-size:18rpx}.mask{position:fixed;z-index:99;inset:0;display:flex;align-items:flex-end;background:rgba(23,43,41,.45)}.drawer{box-sizing:border-box;width:100%;max-height:72vh;padding:28rpx 24rpx calc(22rpx + env(safe-area-inset-bottom));border-radius:24rpx 24rpx 0 0;background:#fff}.drawer-head>view{gap:12rpx}.drawer-head strong{font-size:27rpx}.drawer-head text{font-size:19rpx;color:var(--wms-text-secondary)}.drawer-head>text{color:var(--wms-primary-700)}.zone-head{height:60rpx;margin-top:20rpx;padding:0 18rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx}.zone-list{max-height:50vh}.zone-row{height:68rpx;padding:0 18rpx;border-bottom:1rpx solid var(--wms-border);font-size:21rpx}.zone-row strong{color:var(--wms-primary-700)}</style>
